SELECT /*LGSYSC00040.retrievePreSelectedUserPopupList*/ application_user_id AS user_id ,user_name AS employee_no ,full_name_local AS employee_name ,english_full_name AS english_full_name ,position_name AS position ,organization_name_eng AS department_name ,office_phone_number AS office_phone_number ,mail_addr ,NVL(full_name_local, english_full_name) || mail_addr AS employee_desc ,organization_name_eng AS team_name FROM LGCOM_USER_M_V WHERE (apply_start_date IS NULL OR apply_start_date <= TRUNC(SYSDATE)) AND (apply_end_date IS NULL OR apply_end_date >= TRUNC(SYSDATE)) AND susp_resignation_flag = 'C'
AND application_user_id IN
#{keyValues[${index}]}
AND user_name IN
#{keyValues[${index}]}
ORDER BY application_user_id
